def natural_sort_strings(strings):
    """Sort strings by natural order: digit runs by int value, text by Unicode order.
    Text tokens sort before numeric tokens when kinds differ.
    Shorter equal-prefix token lists sort first; equal keys preserve input order.
    Empty strings are allowed; Unicode digits are treated as text.
    """
    import re

    def _key(s):
        # Split into maximal runs of ASCII digits and non-digit characters
        parts = re.findall(r'[0-9]+|[^0-9]+', s)
        key = []
        for p in parts:
            if p.isascii() and p.isdigit():
                key.append((1, int(p)))
            else:
                key.append((0, p))
        return key

    return sorted(strings, key=_key)
